package com.worklyn.modules.payroll.controller;
import com.worklyn.modules.integration.ActorContext;import com.worklyn.modules.payroll.dto.*;import com.worklyn.modules.payroll.service.PayrollService;import jakarta.validation.constraints.NotBlank;import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/payroll") public class PayrollController {private final PayrollService service;public PayrollController(PayrollService s){service=s;}
 @PostMapping(value="/process",consumes=MediaType.APPLICATION_JSON_VALUE) public PayrollProcessResult process(@RequestBody ProcessRequest req,Authentication auth,@RequestHeader(value="Idempotency-Key",required=false) String header){ActorContext a=ActorContext.from(auth);if(!a.isHrOrAdmin())throw new org.springframework.security.access.AccessDeniedException("Only HR/ADMIN can process payroll");String key=header!=null&&!header.isBlank()?header:req.idempotencyKey();return service.process(req.period(),a.userId(),key);}
 @GetMapping("/period/{period}") public List<PayrollResponse> period(@PathVariable String period,Authentication auth){ActorContext a=ActorContext.from(auth);if(!a.isHrOrAdmin())throw new org.springframework.security.access.AccessDeniedException("Only HR/ADMIN can view period payroll");return service.period(period);}
 @GetMapping({"/payslip", "/payslip/{employeeId}"}) public PayrollResponse payslip(@PathVariable(required=false) String employeeId,@RequestParam String period,Authentication auth){ActorContext a=ActorContext.from(auth);String target=(employeeId!=null&&!employeeId.isBlank())?employeeId:a.employeeId();return service.payslip(target,period,a);}
 @PostMapping("/finalize") public void finalizePeriod(@RequestBody FinalizeRequest req,Authentication auth){service.finalizePeriod(req.period(),ActorContext.from(auth));}
 public record ProcessRequest(@NotBlank String period,String idempotencyKey){} public record FinalizeRequest(@NotBlank String period){}
}
